<script>
	import { regionThe, uncap1, uncap, getData, ord, ud, otherRank, otherEst, qui, cha, cur, figs, get_word } from "./utils";
	
	// import Select from "./ui/Select.svelte";
	import Select from "./dropdown/Select.svelte";
	import { load } from "archieml";
	import robojournalist from 'robojournalist';
	import { LineChart, DoubleVerticalBeeswarmChart, DistDotPlotChart, IndicatorDistDotPlotChart } from './@onsvisual/svelte-charts';
	import { mostRecentYear, singleBeeswarmSubDomains, indicatorsToExclude } from "./config"

	import * as d3 from 'd3';

	var place, region, england, props, subDist;

	import * as someJSON from '../data/healthWithPreviousYearValues.json';

	import * as storJSON from '../data/stories.json';
	import * as someregJSON from '../data/healthindexdata_reg.json';

	import * as indisJSON from '../data/indis.json';
	import * as indikeyJSON from '../data/indikey.json';
	import * as domluJSON from '../data/domlu.json';
	import * as indluJSON from '../data/indlu.json';

	import * as indicatorDistributionData from '../data/binnedIndicatorDistributionsCurrentYear.json';
	import * as subDomainDistributionData from '../data/binnedDistributionsCurrentYear.json';

	// let someJSON = fetch('data/healthWith2019Values.json')
	// let storJSON = fetch('data/stories.json')
	// let someregJSON = fetch('data/healthindexdata_reg.json')
	// let indisJSON = fetch('data/indis.json')

	// import Dropdown from "./dropdown/App.svelte";
	// import Select2 from ".dropdown/Select.svelte";
	
	$: domLU = domluJSON.default
	// $: stor_raw = storJSON.default
	let stor;
	let indis;
	$: if (place) {
		indis = indisJSON.default[place.area]
	}

	$: indikey = indikeyJSON.default
	$: indLU = indluJSON.default

	
	function capi(s) {
		return s.charAt(0).toUpperCase() + s.slice(1);
	}

	$: data = someJSON.default


	$: if (place) {
		region = someregJSON.default[place.region.code]
		england = someregJSON.default['E92000001']
	}
	let options2 = []
	$: if (data) {
		Object.keys(data).forEach(e => {
			options2.push({ 'code': data[e]['area'], 'name': capi(data[e]['name']) })
		}) 
		options2 = options2.sort((a, b) => { 
			if(a.name < b.name) { return -1; }
			if(a.name > b.name) { return 1; }
			return 0;
		 })
	}

	function full_rank(latest_rank) {
		let x = ""
		if ([61, 62, 31, 32, 92, 93, 214, 215, 245, 246, 276, 277].includes(latest_rank)) {
			x = x + "roughly "
		}
		if (latest_rank > 92 && latest_rank < 215) {
			x = x + 'around average among'
		} else {
			if (latest_rank < 93) {
				x = x + "in the top"
			} else {
				x = x + "in the bottom"
			}
			if (latest_rank < 32 | latest_rank > 276) {
				x = x + " " + "10 percent of"
			}
			else if (latest_rank < 62 | latest_rank > 245 ) {
				x = x + " " + "20 percent of"
			}
			else if (latest_rank < 93 | latest_rank > 214 ) {
				x = x + " " + "30 percent of"
			}
		}
		console.log('latest_rank', latest_rank)
		console.log('x', x)
		return x
	}


	function topbotnp(i, yr, sto) {
		// console.log('ston', sto[i].metric)
		// console.log('yrnp', yr)
		// console.log('rank', place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank)
		// console.log('perc', place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307)
		let x = ""
		if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) > 0.4) {
			x = x + 'close to average'
		} else {
			if (place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank>0) {
				x = x + "top"
			} else {
				x = x + "bottom"
			}
			if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.05) {
				x = x + (Math.ceil(Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank)*100/307)/100)
			} 
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.1) {
				x = x + 0.1
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.15) {
				x = x + 0.15
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.2) {
				x = x + 0.2
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.25) {
				x = x + 0.25
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.3) {
				x = x + 0.3
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.4) {
				x = x + 0.4
			}
			else if (Math.abs(place.data[domLU[sto[i].metric]].subdomains[sto[i].metric].total[yr].rank/307) < 0.5) {
				x = x + 0.5
			}
		}
		console.log('x', x)
		return x
	}

	// selected = {code: "E07000124", name: 'Ribble Valley'}
	// selected = {code: "E07000223", name: 'Adur'}
	let subtitle
	let subDomains
	let latest_val
	let latest_rank

	$: console.log("latest_val", latest_val)
	let latest_change
	let indicatorData
	$: console.log('$: selected', selected)
	// $: console.log('$ indicatorData', indicatorData)

	let colWidth;
	// $: colWidth && (selected.code)

	let booleanCheck = false;

	
	$: if(selected) {
		place = data[selected.code]

		place.stories = place.stories.filter( x => x['metric'] != 'Children and young people')

		indicatorData = indisJSON[place["area"]]
		
		stor = storJSON.default[place.area]
		// console.log('stor', storJSON.default)
		// console.log('stor', place.area)
		// console.log('stor', stor)
		console.log("place.stories", place.stories)
		// console.log("stor", stor)

		subDomains = place.stories;
		latest_val = place['data']['Overall']['total']['2021']['value']
		latest_change = place['data']['Overall']['total']['2021']['value'] - place['data']['Overall']['total']['2020']['value']
		latest_rank = place['data']['Overall']['total']['2021']['rank']
		// console.log('latest_val', latest_val)
		// console.log('latest_change', latest_change)
		subtitle = place.name + "'s Health Index score "

		
		if ( Math.abs(latest_change) < 0.3 ) {
			subtitle = subtitle + "remained relatively stable in 2021."
		}
		else {
			if ( latest_change < 0 ) {
				subtitle = subtitle + "decreased "
			}
			else {
				subtitle = subtitle + "increased "
			}

			if ( Math.abs(latest_change) > 2 ) {
				subtitle = subtitle + ""
			}
			else if ( Math.abs(latest_change) < 0.8 ) {
				subtitle = subtitle + "slightly "
			}
			subtitle = subtitle + "in 2021."
		}
		asyncLoop();
	}

	var template

    fetch("text/template.txt")
    // fetch("text/template.pug")
        .then((res) => res.text())
        .then((txt) => (template = txt))

	let loaded = false
	let placeload = false
	const onRosaeNlgLoad = () => {
        loaded = true
        checkHash()
    }

    const checkHash = () => {
        let parent = new URLSearchParams(document.location.search).get("parentUrl");
        let hash = document.location.hash;
        let code = parent ? parent.split("#")[1] : hash ? hash.split("#")[1] : null;
        if (code && code.match(/[EKNSW]\d{8}/)) {
            const item = options2.find(d => d.code === code);
            selected = {code, name: item?.name};
            console.log("selected", selected);
            loadArea(code);
        }
	};

	const asyncLoop = async () => {
		subDist = {}
		for (const i of [0,1,2,3]) {
			const data = await d3.csv('data/'+subDomains[i].metric.replace(/\s/g, '')+'.csv')
			subDist[subDomains[i].metric] = data;
			console.log(subDomains[i].metric.replace(/\s/g, ''))
			console.log(data)

		}
	}


	function whichMet(ob) {
		let ar = []
		Object.keys(ob).forEach(e => {
			let tob = {}
			if (dont_compare1yr.includes(ob.metric)) {
				if (['rank', 'Change6year Rank'].includes(e)) {
					tob[e] = ob[e]
					ar.push(tob)
				}		
			}
			else {
				if (['rank', 'Change1year Rank', 'Change6year Rank'].includes(e)) {
					tob[e] = ob[e]
					ar.push(tob)
				}
			}
		});
		ar.sort((a, b) => {
			return Math.abs(Object.values(a)[0]) - Math.abs(Object.values(b)[0]);
		});
		console.log('premet', ar[0])
		return Object.keys(ar[0])[0]
	}


	function indiSort(ob, index, change) {

		// Create an array that orders objects based on the value of a metric given a qualifier (eg change5year)
		let ar = []
		// console.log('ob', ob)
		Object.keys(ob).forEach(e => {
			let temp_ob = {}
			if (change == 'rank') {
				temp_ob[e] = Math.round(10*ob[e][2021])/10
			}
			else if (change == 'Change6year') {
				temp_ob[e] = Math.round( (ob[e][2021] - ob[e][2015])*10 )/10
			} else {
				temp_ob[e] = Math.round( (ob[e][2021] - ob[e][2020])*10 )/10
				// console.log("e", e)
				// console.log("temp_ob[e]", temp_ob[e])
			}
			ar.push(temp_ob)
		})
		ar.sort((a, b) => {
			return Object.values(b)[0] - Object.values(a)[0];
		});
		// console.log('ar', ar)

		if (index == -1) {
			index = ar.length -1
		}
		else if (index == -2) {
			index = ar.length -2
		}

		let inciar = ["Low birth weight"]

		let indiname = Object.keys(ar[index])[0]

		let incidents = ""

		if (inciar.includes(indiname)) {
			incidents = "incidents of "
		}

		return [incidents+uncap(indikey[indiname]), Object.values(ar[index])[0]]
	}

	// Single select
	let selected = null;
	function doSelect(event) {
		selected = event.detail;
		console.log("selected", selected)

		loadArea(selected['code'])
	}
	function doClear() {
		selected = null;
	}


	function loadArea(code) {
		place = data[code]
		indicatorData = indisJSON[place["area"]]

		booleanCheck=false
		setTimeout(() => booleanCheck = true, 100)
        history.replaceState(null, "", `#${code}`)
	}

	function iterate(obj, pname) {
		Object.keys(obj).forEach(key => {
			if (typeof obj[key] === 'object') {
				iterate(obj[key], pname)
			} else {
				obj[key] = robojournalist(obj[key], {
					plcname: pname,
				})
			}
		})
	}
	$: console.log('place', place)
	$: console.log('indis', indis)

	let twoindis = ['Access to green space', 'Crime', 'Difficulties in daily life', 'Protective measures']
	let dont_compare1yr = ['Crime', 'Difficulties in daily life', 'Mortality', 'Behavioural risk factors']

	function results(place) {

		let caveats = {
			"Difficulties in daily life": `"Frailty" measures hospital admissions as a result of a hip fracture in those aged 65 years and over. Figures may have been affected by higher mortality rates in frailer people during the pandemic, or people being less exposed to injury while less active and staying at home.`,
			"Mental health": `Self-harm figures are counted through hospital admissions and so not all cases are recorded. During the coronavirus pandemic, people may have been less likely to seek help at hospital because of fears of infection or overwhelming services. Suicides per area are based on a three-year period, so these figures show longer-term trends rather than a change year to year. Suicide registrations were also affected by inquest delays in 2020.`,
			"Mortality": `Infant mortality data are based on registrations over a three-year period as numbers in individual areas are low. Death registrations were affected by inquest delays in 2020.`,
			"Behavioural risk factors": `Drug and alcohol misuse are difficult to measure as both can be hidden behaviours. Drug misuse is measured through drug-related crime. For alcohol misuse, we count hospital admissions. A fall in reports of crime or hospital admissions during the pandemic may not represent an actual decrease in alcohol or drug misuse.`,
			"Access to services": `In-person services in this category were limited during the coronavirus pandemic.`
		}
		let caveatsNoise = {
			"Living conditions": `Data for noise complaints are based on the previous year.`,
			"Economic and working conditions": 'Data for child poverty and workplace safety are from 2019.'
		}
		let dont_include = ['Avoidable mortality', 'Life expectancy', 'Healthy eating','Child poverty', 'Workplace safety' ]

		let preres = rosaenlg_en_US.render(template, {
			language: 'en_UK',
			twoindis: twoindis,
			place: place,
			caveats: caveats,
			caveatsNoise: caveatsNoise,
			dont_include: dont_include,
			region: region,
			england: england,
			sto: place.stories,
			orda: place.stories.sort((a, b) =>  b.value  - a.value ),
			parent: uncap1(regionThe(region.name)),
			uncap: uncap,
			get_word: get_word,
			figs: figs,
			otherEst: otherEst,
			cur: cur,
			cha: cha,
			qui: qui,
			otherRank: otherRank,
			ud: ud,
			ord: ord,
			whichMet: whichMet,
			topbotnp: topbotnp,
			domLU: domLU,
			indLU: indLU,
			indis: indis,
			indiSort: indiSort,
			indikey: indikey,
			negs: ['smoking', 'anxiety', 'alcohol misuse', 'drug misuse', 'neighbourhood noise', 'air pollution', 'depression', 'self-harm', 'suicides', 'cancer', 'kidney disease', 'cardiovascular conditions', 'crime', 'unemployment', 'low pay', 'difficulties in daily life', 'avoidable mortality', 'infant mortality', "sexually transmitted infections", "hypertension", "low birth weight", "overweight and obesity in adults", "overweight and obesity in children", "cancer", "cardiovascular conditions", "dementia", "diabetes", "kidney disease", "musculoskeletal conditions", "respiratory conditions", "feelings of anxiety", "avoidable mortality", "infant mortality", "self-harm", "suicides", "rough sleeping", "air pollution", "household overcrowding", "noise complaints", "unemployment", "child poverty", "disability", "hip fractures", "low level crime", "personal crime", "pupil absences", "teenage pregnancy", "sedentary behaviour", "smoking", "alcohol misuse", "drug misuse", "distance to gp services", "distance to pharmacies", "distance to sports or leisure facilities", "mortality", "physiological risk factors", "physical health conditions", "difficulties in daily life", "behavioural risk factors", "mental health conditions", "high blood pressure", "frailty"],
		})
		
		return preres.split(`<div id="esc123"></div>`)
	}

	function makeChartData(place, region, england, i) {
		let temp = []
		let arr = [place, region, england]
		if (place) {
			for (const k in {2015: "", 2016: "", 2017: "", 2018: "", 2019: "", 2020: "", 2021: ""}) {
				for (const j in arr) {
					let top = arr[j].data[domLU[place.stories[i].metric]]['subdomains'][place.stories[i].metric].total
					temp.push({
						year: parseInt(k),
						value: top[k]['value'].toFixed(1),
						group: arr[j].name
					});
				}
			}
		}
		return temp
	}


	function makeProps(i, place) {
		if (i==5) {
			console.log("hello")
			console.log(place);
			console.log(indicatorData);

			return props = {
				area: place,
				data: indicatorData,
				distributionData: indicatorDistributionData,
				width: colWidth,
				indicatorsToExclude: indicatorsToExclude
			}
		}
		else if ((i==0)|(whichMet(subDomains[i]) == 'rank')|(['Access to green space', 'Access to services'].includes(subDomains[i].metric))) {
			// SCATTER
			let chart_data 
			let yKey
			let zKey
			if (i==0) {
				console.log(subDomains)

				chart_data = subDomains.map(d => ({ 'id': (subDomains[i].metric==d.metric)? d.metric:'Other subdomains', 'unique': d['metric'], 'value': d['value'], 'valuePrevYear': d["valuePrevYear"] })).reverse()
				chart_data.sort((a, b) => a.value - b.value)
				yKey = 'unique'
				zKey = 'unique'

				console.log(chart_data)
			}
			else {

				console.log(subDist[subDomains[i].metric]);

				chart_data = subDist[subDomains[i].metric].map(d => ({ 'id': d['RGN21NM'], 'unique': d['AREANM'], 'value': (d['time7']), 'valuePrevYear': (d['time6']) }))

				chart_data.forEach((item, i) => {
					if (item.unique==place.name) {
						item.id = place.name
					} else if (item.id == place.region.name) {
						item.id = region.name
					} else {
						item.id = "Rest of England"
					}
				});
				chart_data.push({'id': 'England', 'unique': 'England', 'value': england.data[domLU[subDomains[i].metric]].subdomains[subDomains[i].metric].total[mostRecentYear].value, 'valuePrevYear': england.data[domLU[subDomains[i].metric]].subdomains[subDomains[i].metric].total[mostRecentYear-1].value})

				chart_data = chart_data.filter(d => d.id != 'Rest of England')

				yKey = null
				zKey = 'id'

			}

			return props = {
				i: i,
				topic: subDomains[i],
				data: chart_data,
				xKey: "value",
				yKey: yKey,
				zKey: zKey,
				distributionData: subDomainDistributionData,
				width: colWidth,
				singleBeeswarmSubDomains: singleBeeswarmSubDomains
				// title: "Multi-line chart"
			}
		} else {
			// LINE
			return props = {
				topic: subDomains[i],
				data: makeChartData(place, region, england, i),
				xKey: "year",
				yKey: "value",
				zKey: "group",
				area: false,
				width: colWidth
				
				// title: "Multi-line chart"
			}
		}
	}

    let embedLocal = true;
    let embedJS = true;

    function makeEmbedCode(selected, embedLocal, embedJS) {
        let url = "https://www.ons.gov.uk/visualisations/dvc2623/";
        let title = "Health index";
        if (selected?.code && embedLocal) {
            url += `#${selected.code}`;
            title += ` for ${selected.name}`;
        }
        
        return embedJS ?
            `<div id="health-index"></div>
<script src="http://cdn.ons.gov.uk/vendor/pym/1.3.2/pym.min.js"></\script>
<script>var pymParent = new pym.Parent("health-index", "${url}", {name: "health-index", title: "${title}"});</\script>` :
            `<iframe height="550px" width="100%" border="0" src="${url}"></iframe>`
    }
    function copyEmbedCode() {
        navigator.clipboard.writeText(embedCode)
		    .then(() => alert("Embed code copied to clipboard."));
    }

    $: embedCode = makeEmbedCode(selected, embedLocal, embedJS);


</script>

<svelte:head>
	<script src="./rosaenlg.js" on:load="{onRosaeNlgLoad}"></script>
</svelte:head>

<img id="imagebanner" src="Health-index-tool_webpage-illustration-v4_1@2x.png" alt="Health Index Graphic" style="width: 637px;">
<div id="topdiv" style="background-color: #2060951A; width: 637px; margin-top: -120px;">
	<div style='height: 120px;'></div>
	<div style='padding: 20px;'>
		<h4 id='dropdowntitle'>What is my area’s Health Index score?</h4>

		<div>
			<p id='dropdowntext'>
				Choose an area to see how different aspects of health have changed.
			</p>
			<div id="dropdown">
				<div style="widht: 79.79px; height: 79.79px; margin: 20px auto;">

					{#if (options2.length==307)}

					<form>
						<!-- <label for="single">Select one local authority:</label> -->
						<!-- <Select id="single" idKey="areacd" labelKey="areanm" {items} on:select={doSelect} on:clear={doClear}/> -->
						<Select id="single" idKey="code" labelKey="name" items={options2} on:select={doSelect} on:clear={doClear}/>
					</form>
					
					{/if}


					<!-- <Select options={options2} bind:selected value={selected} label="name" search={true} on:select="{() => { if (selected) { loadArea(selected.code) }}}"/>				   -->
				</div>
			</div>

		</div>
		{#if place}

		{#if loaded}
		{#if options2}
		{#if template}
		{#if domLU}
		{#if indLU}
			<hr style="border: 1px solid #3D6092; color: #3D6092; background-color: #3D6092;">

			<div style="display: flex; justify-content: space-around; flex-direction: row; align-items:center; margin: 20px 20px 20px 0px; position: relative;">
				<p class="mainScoreAccompText" style="flex-basis: auto; font-weight: 700; font-size: 24px; color: rgb(32, 96, 149); float: left; line-height: 28px; margin-bottom: 0px; max-width: 80%;">Health Index score for <span style="color: #00A3A6;">{place.name}: </span></p>
				<div style="flex-basis:auto">
					<div style="font-weight: 700; font-size: 25px; background: #4DBFC1; color: white; height: 77px; width: 77px; border-radius: 40px; text-align: center; line-height: 80px; border: white 2px solid; outline: #F3985C 4px solid;">{(Math.round(latest_val*10)/10).toFixed( 1 ) }</div>
				</div>
			</div>
			<!-- <span style="height: 25px; width: 25px; background-color: "></span> -->
			<!-- <ellipse cx="200" cy="80" rx="100" ry="50" /> -->
			<hr style="border: 1px solid #3D6092; color: #3D6092; background-color: #3D6092; margin-bottom: 20px;">
			<p style="font-weight: 400; font-size: 18px; color: #206095;">{subtitle}</p>

			<p style="font-weight: 400; font-size: 18px; color: #206095;">{place.name} has an overall Health Index score of {(Math.round(latest_val*10)/10).toFixed( 1 ) }, which <span style="color: #00A3A6; font-weight: 700;">{latest_change>0?'is up' : latest_change<0? 'is down' : 'has changed'} { (Math.round(Math.abs(latest_change)*10)/10).toFixed( 1 ) } points</span> compared with the previous year.</p>
			<p style="font-weight: 400; font-size: 18px; color: #206095;">A score of 100 represents average levels of health in England in 2015. A higher number always means better health and a lower number means worse health.</p>
			<p style="font-weight: 400; font-size: 18px; color: #206095;">{place.name} ranked {full_rank(latest_rank)} local authority areas in England for health in 2021.</p>
		{:else}
			<div style="padding-left: 40%;">Loading...</div>
		{/if}
		{/if}
		{/if}
		{/if}
		{/if}
		{/if}

	</div>
</div>

<div style="height: 10px"></div>
{#if loaded}
{#if options2}
{#if template}
{#if domLU}
{#if indLU}
		<div class="wrapper">

		<div class="col" bind:clientWidth={colWidth}>
		<div style="margin-right: 32px;">
			{#if place}	
			{#if indicatorData}	

			{#each results(place) as res, i (i)}
				{@html res}
				{#if i<4}
					{#if subDist[subDomains[i].metric]}
						<svelte:component this="{
						(i==0)? DistDotPlotChart : 
						(['Access to green space', 'Access to services'].includes(subDomains[i].metric)) ? DoubleVerticalBeeswarmChart :
						(whichMet(subDomains[i]) == 'rank') ? DoubleVerticalBeeswarmChart:
						LineChart}" 
						{...makeProps(i, place)}
						colWidth={colWidth}/>
					{/if}

				<!-- {:else if i==4}
					<svelte:component this="{(i==4)? IndicatorDistDotPlotChart : IndicatorDistDotPlotChart}" {...makeProps(i, place, indicatorData)}/> -->
				{/if}
			{/each}

			{#if booleanCheck}
					<svelte:component this="{IndicatorDistDotPlotChart}" {...makeProps(5, place)}
					colWidth={colWidth}
					/>
			{/if}


				

			{/if}
			{/if}
		</div>
		</div>
		</div>
        <div class="wrapper">
            <div class="col">
                <details class="embed-code">
                    <summary>Embed code</summary>
                    <form on:submit|preventDefault={copyEmbedCode}>
                        <strong>Embed this interactive</strong>
                        {#if selected}
                        <label><input type="checkbox" bind:checked={embedLocal}/> Pre-select {selected.name}</label>
                        {/if}
                        <label><input type="checkbox" bind:checked={embedJS}/> Responsive embed (requires Javascript)</label>
                        <textarea rows=3 readonly>{embedCode}</textarea>
                        <button type="submit">Copy embed code</button>
                    </form>
                </details>
            </div>
        </div>

{:else}
	<div style="padding-left: 40%;">Loading...</div>
{/if}
{/if}
{/if}
{/if}
{/if}

