<script>
    import { curveStepBefore } from "d3";

export let key, x, yPosition, violinPlotData, violinFuncs, seriesParametersArray, circleData, label, labelYValue = 0, backgroundToLabel = true, labelFontSize = "14px", radius=8, hoverLabel = false, indicator = false;

function splitStringEqually(inputString) {
  // Split the input string into an array of words
  const words = inputString.trim().split(' ');

  // Calculate the approximate midpoint
  const midpoint = Math.ceil(words.length / 2);

  // Split the words array into two parts
  const firstHalf = words.slice(0, midpoint);
  const secondHalf = words.slice(midpoint);

  // Join the words back into strings
  const firstString = firstHalf.join(' ');
  const secondString = secondHalf.join(' ');

  return [firstString, secondString];
}

function splitStringIntoThree(str) {
  const words = str.split(" ");
  const totalWords = words.length;
  const third = Math.ceil(totalWords / 3);

  const firstString = words.slice(0, third).join(" ");
  const secondString = words.slice(third, 2 * third).join(" ");
  const thirdString = words.slice(2 * third).join(" ");

  return [firstString, secondString, thirdString];
}

function handleMouseOver(e) {

        d3.select(this.parentNode.parentNode.parentNode).selectAll(".plot-group").attr("opacity", 0.25)
        d3.select(this.parentNode.parentNode).selectAll("circle").attr("opacity", 0)
        
        d3.select(this).attr("opacity", 1).style("fill", "orange")
        d3.select(this.parentNode).select(".tooltipLabel").selectAll("text").attr("opacity", 1)
        d3.select(this.parentNode.parentNode).attr("opacity", 1)
        
}

function handleMouseOut(e) {
		
        d3.select(this.parentNode.parentNode.parentNode).selectAll(".plot-group").attr("opacity", 1)
        d3.select(this.parentNode.parentNode).selectAll("circle").attr("opacity", 1)
        
        d3.select(this).attr("opacity", 1).style("fill", null)
        d3.select(this.parentNode).select(".tooltipLabel").selectAll("text").attr("opacity", 0)
}


</script>

<g class="plot-group"
transform={"translate("+0+","+yPosition+")"}>

    {#if !key}

        <line
        y1=0
        y2=0
        x1=5
        x2={x(Math.min(...circleData))}
        stroke="#e0dede"
        fill="none"
        stroke-width="0.5px"
        opacity=1
        ></line>

    {/if}

    <g class="distribution-curve-group">

        {#each violinFuncs as violinFunc}

            <path
            d={violinFunc(violinPlotData)}
            stroke="none"
            fill="#e0dede"
            opacity=1
            ></path>
            
        {/each}
    
    </g>

    {#if label === undefined || label.length < 25 || !indicator}

    {#if !key}

        {#if backgroundToLabel}

            <text class="subdomain-labels-border"
            y={4+labelYValue}
            x=0
            stroke="white"
            fill="white"
            font-size={labelFontSize}
            text-anchor="start"
            stroke-width="6px"
            >{label}</text>

        {/if}

        <text class="subdomain-labels-main"
        y={4+labelYValue}
        x=0
        stroke="none"
        fill="#333"
        font-size={labelFontSize}
        text-anchor="start"
        >{label}</text>

    {/if}

    {:else if label.length < 40}

        {#if backgroundToLabel}

        <text class="subdomain-labels-border"
        y={3+labelYValue}
        x=0
        stroke="white"
        fill="white"
        font-size={"12px"}
        text-anchor="start"
        stroke-width="6px"
        >{splitStringEqually(label)[0]}</text>

        <text class="subdomain-labels-border"
        y={16+labelYValue}
        x=0
        stroke="white"
        fill="white"
        font-size={"12px"}
        text-anchor="start"
        stroke-width="6px"
        >{splitStringEqually(label)[1]}</text>

        {/if}

        <text class="subdomain-labels-main"
        y={3+labelYValue}
        x=0
        stroke="none"
        fill="#333"
        font-size={"12px"}
        text-anchor="start"
        >{splitStringEqually(label)[0]}</text>

        <text class="subdomain-labels-main"
        y={16+labelYValue}
        x=0
        stroke="none"
        fill="#333"
        font-size={"12px"}
        text-anchor="start"
        >{splitStringEqually(label)[1]}</text>

    {:else}

    {#if backgroundToLabel}

    <text class="subdomain-labels-border"
    y={3+labelYValue}
    x=0
    stroke="white"
    fill="white"
    font-size={"12px"}
    text-anchor="start"
    stroke-width="6px"
    >{label === "Young people in education, employment and apprenticeships" ? "Young people in education," : splitStringIntoThree(label)[0]}</text>

    <text class="subdomain-labels-border"
    y={16+labelYValue}
    x=0
    stroke="white"
    fill="white"
    font-size={"12px"}
    text-anchor="start"
    stroke-width="6px"
    >{label === "Young people in education, employment and apprenticeships" ? "employment and" : splitStringIntoThree(label)[1]}</text>

    <text class="subdomain-labels-border"
    y={29+labelYValue}
    x=0
    stroke="white"
    fill="white"
    font-size={"12px"}
    text-anchor="start"
    stroke-width="6px"
    >{label === "Young people in education, employment and apprenticeships" ? "apprenticeships" : splitStringIntoThree(label)[2]}</text>

    {/if}

    <text class="subdomain-labels-main"
    y={3+labelYValue}
    x=0
    stroke="none"
    fill="#333"
    font-size={"12px"}
    text-anchor="start"
    >{label === "Young people in education, employment and apprenticeships" ? "Young people in education," : splitStringIntoThree(label)[0]}</text>

    <text class="subdomain-labels-main"
    y={16+labelYValue}
    x=0
    stroke="none"
    fill="#333"
    font-size={"12px"}
    text-anchor="start"
    >{label === "Young people in education, employment and apprenticeships" ? "employment and" : splitStringIntoThree(label)[1]}</text>

    <text class="subdomain-labels-main"
    y={29+labelYValue}
    x=0
    stroke="none"
    fill="#333"
    font-size={"12px"}
    text-anchor="start"
    >{label === "Young people in education, employment and apprenticeships" ? "apprenticeships" : splitStringIntoThree(label)[2]}</text>

    



    {/if}

    {#each seriesParametersArray as series, j}

        <g>

        <circle on:mouseover={hoverLabel ? handleMouseOver: null} on:focus={null} on:mouseleave={hoverLabel ? handleMouseOut: null}
        cx={x(circleData[j])}
        cy={circleData.length == 2 & seriesParametersArray.length == 2 ? (Math.abs(x(circleData[0])-x(circleData[1]))>10 ? 0 : [4,-4][j]) : 0}
        r={radius}
        stroke="white"
        fill={series["color"]}
        stroke-width="1.5px"
        ></circle>

        {#if hoverLabel}

            <g class=tooltipLabel>

                <text
                x={x(circleData[j])}
                y={circleData.length == 2 ? (Math.abs(x(circleData[0])-x(circleData[1]))>10 ? -radius*1.5 : -radius*1.5+[4,-4][j]) : -radius*1.5}
                font-size={"14px"}
                pointer-events="none"
                stroke-width="3px"
                opacity=0
                stroke={"white"}
                fill={"white"}
                text-anchor="middle"
                >{circleData[j].toFixed(1)}</text>

                <text
                x={x(circleData[j])}
                y={circleData.length == 2 ? (Math.abs(x(circleData[0])-x(circleData[1]))>10 ? -radius*1.5 : -radius*1.5+[4,-4][j]) : -radius*1.5}
                font-size={"14px"}
                pointer-events="none"
                stroke-width="1px"
                opacity=0
                stroke={series["color"]}
                fill={series["color"]}
                text-anchor="middle"
                >{circleData[j].toFixed(1)}</text>

            </g>
        
        {/if}

        </g>
    {/each}

</g>